#!/usr/bin/env node
/**
 * PreToolUse guard for Edit / Write / NotebookEdit.
 *
 * Blocks changes that must never be made by hand or by an agent:
 * - secrets (.env, private keys, certificate stores, HSM tokens),
 * - committed Prisma migrations and the migration lock file,
 * - generated files (Prisma client, OpenAPI app types, pnpm lockfile, build output),
 * - the guardrails themselves (.claude/settings.json, .claude/hooks/).
 *
 * Output: a JSON "deny" decision on stdout, or nothing when the edit is fine.
 */
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import path from 'node:path';

const projectDir = process.env.CLAUDE_PROJECT_DIR ?? process.cwd();

/** Repository-relative POSIX path, or null when the file is outside the project. */
function toRepoPath(filePath) {
  const relative = path.relative(projectDir, path.resolve(projectDir, filePath));
  if (relative.startsWith('..') || path.isAbsolute(relative)) return null;
  return relative.split(path.sep).join('/');
}

function isTrackedByGit(repoPath) {
  try {
    execFileSync('git', ['ls-files', '--error-unmatch', '--', repoPath], {
      cwd: projectDir,
      stdio: 'ignore',
    });
    return true;
  } catch {
    return false;
  }
}

const RULES = [
  {
    test: (p) => /(^|\/)\.env(\.(?!example$|sample$|template$)[^/]+)?$/i.test(p),
    reason:
      'Secret files (.env) are managed by the user only. Document new variables in .env.example with a placeholder and ask the user to set the real value.',
  },
  {
    test: (p) =>
      /\.(pem|key|p12|pfx|jks|keystore)$/i.test(p) ||
      /(^|\/)id_(rsa|ed25519|ecdsa)$/.test(p) ||
      /^infra\/(secrets|softhsm\/tokens)\//.test(p),
    reason:
      'Keys, certificates and HSM tokens are generated by scripts at runtime and never written by an agent or committed.',
  },
  {
    test: (p) => /(^|\/)prisma\/migrations\/migration_lock\.toml$/.test(p),
    reason: 'migration_lock.toml is maintained by Prisma Migrate.',
  },
  {
    test: (p) => /(^|\/)prisma\/migrations\/[^/]+\/migration\.sql$/.test(p) && isTrackedByGit(p),
    reason:
      'This migration is already committed and may be applied somewhere. Never edit it — create a new migration with `pnpm run api:db:migrate:dev --name <change>` (see the db-migration skill).',
  },
  {
    test: (p) =>
      p === 'pnpm-lock.yaml' ||
      /(^|\/)src\/generated\//.test(p) ||
      p === 'app/src/shared/api/schema.d.ts' ||
      p === 'api/openapi.json',
    reason:
      'Generated file. Regenerate it instead: `pnpm install`, `pnpm run api:prisma:generate`, `pnpm run api:openapi:generate`, `pnpm run app:api:types`.',
  },
  {
    test: (p) => /(^|\/)(dist|dist-native|build|coverage|\.expo|web-build)\//.test(p),
    reason: 'Build output is generated; change the sources instead.',
  },
  {
    test: (p) => p === '.claude/settings.json' || p.startsWith('.claude/hooks/'),
    reason:
      'Guardrail files are maintained by the project owner. Propose the change in chat with the exact diff; the user applies it.',
  },
];

function main() {
  let input;
  try {
    input = JSON.parse(readFileSync(0, 'utf8'));
  } catch {
    process.stderr.write('protect-files: could not parse hook input\n');
    process.exit(2);
  }
  const filePath = input?.tool_input?.file_path ?? input?.tool_input?.notebook_path;
  if (typeof filePath !== 'string' || filePath === '') return;
  const repoPath = toRepoPath(filePath);
  if (repoPath === null) return;
  const rule = RULES.find(({ test }) => test(repoPath));
  if (!rule) return;
  process.stdout.write(
    JSON.stringify({
      hookSpecificOutput: {
        hookEventName: 'PreToolUse',
        permissionDecision: 'deny',
        permissionDecisionReason: `Blocked by repository policy (${repoPath}): ${rule.reason}`,
      },
    }),
  );
}

main();
